  4	final class IntBinaryHeap {
  5	    private static final int DEFAULT_CAPACITY = 10;
  6	
  7	    private int[] elements;
  8	    private int size;
  9	
 10	    IntBinaryHeap() {
 11	        this(DEFAULT_CAPACITY);
 12	    }
 13	
 14	    IntBinaryHeap(int initialCapacity) {
 15	        if (initialCapacity < 0) {
 16	            throw new IllegalArgumentException("initial capacity must be non-negative");
 17	        }
 18	
 19	        elements = new int[initialCapacity];
 20	        size = 0;
 21	    }
 22	
 23	    IntBinaryHeap(int[] values) {
 24	        if (values == null) {
 25	            throw new IllegalArgumentException("values must not be null");
 26	        }
 27	
 28	        elements = copyOf(values);
 29	        size = values.length;
 30	        rebuildHeap();
 31	    }
 32	
 33	    boolean offer(int value) {
 34	        ensureCapacity(size + 1);
 35	        elements[size] = value;
 36	        siftUp(size);
 37	        size++;
 38	        return true;
 39	    }
 40	
 41	    void addAll(int... values) {
 42	        if (values == null) {
 43	            throw new IllegalArgumentException("values must not be null");
 44	        }
 45	
 46	        if (values.length == 0) {
 47	            return;
 48	        }
 49	
 50	        appendAll(values);
 51	        rebuildHeap();
 52	    }
 53	
 54	    int peek() {
 55	        ensureNotEmpty();
 56	        return elements[0];
 57	    }
 58	
 59	    int removeMin() {
 60	        ensureNotEmpty();
 61	        return removeAt(0);
 62	    }
 63	
 64	    int removeAt(int index) {
 65	        validateOccupiedIndex(index);
 66	
 67	        int removedValue = elements[index];
 68	        int lastIndex = size - 1;
 69	        int lastValue = elements[lastIndex];
 70	        elements[lastIndex] = 0;
 71	        size--;
 72	        if (index == lastIndex) {
 73	            return removedValue;
 74	        }
 75	
 76	        elements[index] = lastValue;
 77	        restoreHeapAt(index);
 78	        return removedValue;
 79	    }
 80	
 81	    void updateValue(int index, int newValue) {
 82	        validateOccupiedIndex(index);
 83	
 84	        int currentValue = elements[index];
 85	        elements[index] = newValue;
 86	        if (newValue < currentValue) {
 87	            siftUp(index);
 88	            return;
 89	        }
 90	
 91	        if (newValue > currentValue) {
 92	            siftDown(index);
 93	        }
 94	    }
