122	    private void appendAll(int[] values) {
123	        int originalSize = size;
124	        ensureCapacity(originalSize + values.length);
125	        System.arraycopy(values, 0, elements, originalSize, values.length);
126	        size += values.length;
127	    }
128	
129	    private void rebuildHeap() {
130	        for (int index = parentIndex(size - 1); index >= 0; index--) {
131	            siftDown(index);
132	        }
133	    }
134	
135	    private void ensureCapacity(int requiredCapacity) {
136	        if (requiredCapacity <= elements.length) {
137	            return;
138	        }
139	
140	        int newCapacity = elements.length == 0 ? 1 : elements.length;
141	        while (newCapacity < requiredCapacity) {
142	            newCapacity *= 2;
143	        }
144	
145	        elements = Arrays.copyOf(elements, newCapacity);
146	    }
147	
148	    private void siftUp(int index) {
149	        while (index > 0) {
150	            int parentIndex = parentIndex(index);
151	            if (elements[parentIndex] <= elements[index]) {
152	                return;
153	            }
154	
155	            swap(index, parentIndex);
156	            index = parentIndex;
157	        }
158	    }
159	
160	    private void siftDown(int index) {
161	        while (true) {
162	            int leftChildIndex = leftChildIndex(index);
163	            int rightChildIndex = rightChildIndex(index);
164	            int smallestIndex = index;
165	
166	            if (leftChildIndex < size && elements[leftChildIndex] < elements[smallestIndex]) {
167	                smallestIndex = leftChildIndex;
168	            }
169	
170	            if (rightChildIndex < size && elements[rightChildIndex] < elements[smallestIndex]) {
171	                smallestIndex = rightChildIndex;
172	            }
173	
174	            if (smallestIndex == index) {
175	                return;
176	            }
177	
178	            swap(index, smallestIndex);
179	            index = smallestIndex;
180	        }
181	    }
