183	    private void restoreHeapAt(int index) {
184	        if (index > 0 && elements[index] < elements[parentIndex(index)]) {
185	            siftUp(index);
186	            return;
187	        }
188	
189	        siftDown(index);
190	    }
191	
192	    private void swap(int firstIndex, int secondIndex) {
193	        int temp = elements[firstIndex];
194	        elements[firstIndex] = elements[secondIndex];
195	        elements[secondIndex] = temp;
196	    }
