212	    private int parentIndex(int index) {
213	        return (index - 1) / 2;
214	    }
215	
216	    private int leftChildIndex(int index) {
217	        return index * 2 + 1;
218	    }
219	
220	    private int rightChildIndex(int index) {
221	        return index * 2 + 2;
222	    }
