229	    private static void assertThrows(
230	        String message,
231	        Class<? extends Throwable> expectedType,
232	        ThrowingRunnable action
233	    ) {
234	        try {
235	            action.run();
236	        } catch (Throwable thrown) {
237	            if (expectedType.isInstance(thrown)) {
238	                return;
239	            }
240	
241	            throw new AssertionError(
242	                message + ": expected " + expectedType.getSimpleName()
243	                    + ", got " + thrown.getClass().getSimpleName(),
244	                thrown
245	            );
246	        }
247	
248	        throw new AssertionError(
249	            message + ": expected " + expectedType.getSimpleName() + " to be thrown"
250	        );
251	    }
